def apply_callback(seen, order_no, ship):
    if order_no in seen:
        seen[order_no] = ship()
        return seen[order_no]
    result = ship()
    return result

verification_tests:
from target import *
def _replay():
    seen = {}
    calls = {'n': 0}
    def ship():
        calls['n'] += 1
        return 2
    first = apply_callback(seen, 'a', ship)
    second = apply_callback(seen, 'a', ship)
    return [first, second]

def _shipped_once():
    seen = {}
    calls = {'n': 0}
    def ship():
        calls['n'] += 1
        return 5
    apply_callback(seen, 'b', ship)
    apply_callback(seen, 'b', ship)
    return calls['n']


def test_experience_1():
    assert _shipped_once() == 1


def test_experience_2():
    assert apply_callback({}, 'a', lambda: 1) == 1


def test_experience_3():
    assert _replay() == [2, 2]
